script:
# Add contractual service charges to draft rental invoices.
# No imports or string.format are used.

if (
    doc.docstatus == 0
    and not doc.get("is_return")
    and doc.get("subscription")
):
    lease_type = frappe.get_meta("Sales Invoice").get_field(
        "subscription"
    ).options

    lease = frappe.get_doc(lease_type, doc.subscription)
    lease.check_permission("read")

    charges = lease.get("custom_service_charges") or []

    # Preserve ordinary invoice items.
    # Previously generated service lines will be rebuilt.
    ordinary_items = []

    for item in doc.get("items") or []:
        if not item.get("custom_lease_charge_reference"):
            ordinary_items.append(item)

    has_generated_charges = (
        len(ordinary_items) != len(doc.get("items") or [])
    )

    if charges or has_generated_charges:

        if not doc.get("from_date") or not doc.get("to_date"):
            frappe.throw(
                "يجب تحديد From Date وTo Date لفاتورة الإيجار."
            )

        period_start = frappe.utils.getdate(doc.from_date)
        period_end = frappe.utils.getdate(doc.to_date)

        if period_end < period_start:
            frappe.throw(
                "تاريخ نهاية فترة الفاتورة يسبق تاريخ بدايتها."
            )

        # Find charges reserved in other draft or submitted invoices.
        other_invoices = frappe.get_all(
            "Sales Invoice",
            filters={
                "subscription": doc.subscription,
                "docstatus": ["!=", 2],
                "is_return": 0,
                "name": ["!=", doc.name or ""]
            },
            fields=["name"],
            limit_page_length=0
        )

        invoice_names = []

        for invoice in other_invoices:
            invoice_names.append(invoice.name)

        billed_keys = []

        if invoice_names:
            billed_rows = frappe.get_all(
                "Sales Invoice Item",
                filters={
                    "parent": ["in", invoice_names],
                    "parenttype": "Sales Invoice",
                    "parentfield": "items"
                },
                fields=[
                    "custom_lease_charge_reference",
                    "custom_charge_due_date"
                ],
                limit_page_length=0
            )

            for billed_row in billed_rows:
                reference = billed_row.get(
                    "custom_lease_charge_reference"
                )
                due_date = billed_row.get(
                    "custom_charge_due_date"
                )

                if reference and due_date:
                    billed_keys.append(
                        str(reference)
                        + "|"
                        + str(frappe.utils.getdate(due_date))
                    )

        frequency_months = {
            "Monthly": 1,
            "Quarterly": 3,
            "Semiannual": 6,
            "Annual": 12
        }

        pending_charges = []

        for charge in charges:
            method = charge.get("charge_method")

            # Included services do not create additional invoice lines.
            if method == "Included in Rent":
                continue

            if method != "Fixed Amount":
                frappe.throw(
                    "طريقة رسوم غير مدعومة في سطر الخدمات رقم "
                    + str(charge.idx)
                )

            if not charge.get("service_item"):
                frappe.throw(
                    "يرجى تحديد صنف الخدمة في السطر رقم "
                    + str(charge.idx)
                )

            amount = frappe.utils.flt(charge.get("amount"))

            if amount <= 0:
                frappe.throw(
                    "مبلغ الخدمة يجب أن يكون أكبر من صفر في السطر رقم "
                    + str(charge.idx)
                )

            if charge.get("currency") != doc.currency:
                frappe.throw(
                    "عملة الخدمة لا تطابق عملة الفاتورة في السطر رقم "
                    + str(charge.idx)
                )

            service_start = charge.get("start_date") or lease.get(
                "start_date"
            )
            service_end = charge.get("end_date") or lease.get(
                "end_date"
            )

            if not service_start or not service_end:
                frappe.throw(
                    "يرجى تحديد بداية ونهاية الخدمة في العقد."
                )

            service_start = frappe.utils.getdate(service_start)
            service_end = frappe.utils.getdate(service_end)

            if service_end < service_start:
                frappe.throw(
                    "فترة الخدمة غير صحيحة في السطر رقم "
                    + str(charge.idx)
                )

            frequency = charge.get("frequency")
            due_dates = []

            if frequency == "With Rent Invoice":
                # One charge per rental invoice period.
                if (
                    period_start <= service_end
                    and period_end >= service_start
                ):
                    due_dates.append(
                        max(period_start, service_start)
                    )

            elif frequency == "One Time":
                if (
                    period_start <= service_start
                    and service_start <= period_end
                ):
                    due_dates.append(service_start)

            elif frequency in frequency_months:
                step = frequency_months[frequency]
                occurrence = 0
                due = service_start
                last_date = min(period_end, service_end)

                while due <= last_date:
                    if due >= period_start:
                        due_dates.append(due)

                    occurrence = occurrence + 1

                    if occurrence > 1200:
                        frappe.throw(
                            "فترة الخدمة طويلة جدًا؛ راجع تواريخ العقد."
                        )

                    # Always calculate from the original start date,
                    # avoiding drift for dates such as January 31.
                    due = frappe.utils.getdate(
                        frappe.utils.add_months(
                            service_start,
                            occurrence * step
                        )
                    )

            else:
                frappe.throw(
                    "دورية غير مدعومة في سطر الخدمات رقم "
                    + str(charge.idx)
                )

            for due in due_dates:
                key = str(charge.name) + "|" + str(due)

                if key not in billed_keys:
                    pending_charges.append({
                        "item_code": charge.service_item,
                        "qty": 1,
                        "rate": amount,
                        "custom_lease_charge_reference": charge.name,
                        "custom_charge_due_date": due
                    })

                    billed_keys.append(key)

        doc.set("items", ordinary_items)

        for values in pending_charges:
            doc.append("items", values)

        # Fetch standard item details, accounts, UOM and defaults.
        # The normal invoice validation then recalculates totals.
        if pending_charges or has_generated_charges:
            doc.run_method("set_missing_values")

permission_doc = frappe.new_doc("Subscription")
permission_doc.check_permission("read")

start_value = frappe.form_dict.get("start_date")
end_value = frappe.form_dict.get("end_date")
current_name = frappe.form_dict.get("current_lease")

if not start_value or not end_value:
    frappe.throw("حدد بداية العقد ونهايته أولًا.")

start = frappe.utils.getdate(start_value)
end = frappe.utils.getdate(end_value)

if end < start:
    frappe.throw("نهاية العقد يجب ألا تسبق بدايته.")

if current_name:
    current = frappe.get_doc("Subscription", current_name)
    current.check_permission("read")

leases = frappe.get_all(
    "Subscription",
    filters={
        "docstatus": ["!=", 2],
        "start_date": ["<=", str(end)]
    },
    fields=["name", "start_date", "end_date", "status"],
    limit_page_length=0
)

overlapping_names = []

for lease in leases:

    if lease.name != current_name and lease.status != "Cancelled":

        existing_end = frappe.utils.getdate(
            lease.end_date or "9999-12-31"
        )

        if existing_end >= start:
            overlapping_names.append(lease.name)

blocked_plans = []
blocked_items = []

if overlapping_names:

    plans_field = frappe.get_meta("Subscription").get_field("plans")

    if not plans_field or not plans_field.options:
        frappe.throw("تعذر تحديد جدول خطط الإيجار.")

    occupied_rows = frappe.get_all(
        plans_field.options,
        filters={
            "parent": ["in", overlapping_names],
            "parenttype": "Subscription",
            "parentfield": "plans"
        },
        fields=["plan"],
        limit_page_length=0
    )

    for row in occupied_rows:
        if row.plan and row.plan not in blocked_plans:

            blocked_plans.append(row.plan)

            occupied_item = frappe.db.get_value(
                "Subscription Plan", row.plan, "item"
            )

            if occupied_item and occupied_item not in blocked_items:
                blocked_items.append(occupied_item)

plans = frappe.get_list(
    "Subscription Plan",
    fields=["name", "item"],
    order_by="name asc",
    limit_page_length=0
)

available = []

for plan in plans:

    if (
        plan.item
        and plan.name not in blocked_plans
        and plan.item not in blocked_items
    ):

        unit = frappe.db.get_value(
            "Item",
            plan.item,
            ["disabled", "has_variants"],
            as_dict=True
        )

        if unit and not unit.disabled and not unit.has_variants:
            available.append(plan.name)

frappe.response["message"] = {
    "plans": available
}

from_date = frappe.form_dict.get("from_date")
to_date = frappe.form_dict.get("to_date")
building = frappe.form_dict.get("building")

if bool(from_date) != bool(to_date):
    frappe.throw("يرجى تحديد تاريخ البداية والنهاية معًا.")

period_mode = bool(from_date and to_date)

if period_mode:
    start_date = frappe.utils.getdate(from_date)
    end_date = frappe.utils.getdate(to_date)
else:
    start_date = frappe.utils.getdate(frappe.utils.today())
    end_date = start_date

if end_date < start_date:
    frappe.throw("تاريخ النهاية يجب ألا يسبق تاريخ البداية.")

plan_filters = {}

if building:
    plan_filters["custom_building"] = building

plans = frappe.get_list(
    "Subscription Plan",
    filters=plan_filters,
    fields=[
        "name",
        "item",
        "custom_building",
        "cost",
        "currency",
        "billing_interval",
        "billing_interval_count",
    ],
    order_by="custom_building asc, name asc",
    limit_page_length=0,
)

plan_names = []

for plan in plans:
    plan_names.append(plan.name)

blocked_plans = []

if plan_names:
    leases = frappe.get_all(
        "Subscription",
        filters={
            "docstatus": ["!=", 2],
            "status": ["!=", "Cancelled"],
            "start_date": ["<=", end_date],
        },
        fields=["name", "end_date"],
        limit_page_length=0,
    )

    overlapping_leases = []

    for lease in leases:
        if (
            not lease.end_date
            or frappe.utils.getdate(lease.end_date) >= start_date
        ):
            overlapping_leases.append(lease.name)

    if overlapping_leases:
        lease_meta = frappe.get_meta("Subscription")
        child_doctype = lease_meta.get_field("plans").options

        occupied_rows = frappe.get_all(
            child_doctype,
            filters={
                "parenttype": "Subscription",
                "parentfield": "plans",
                "parent": ["in", overlapping_leases],
                "plan": ["in", plan_names],
            },
            fields=["plan"],
            limit_page_length=0,
        )

        for row in occupied_rows:
            if row.plan not in blocked_plans:
                blocked_plans.append(row.plan)

units = []
available_count = 0
occupied_count = 0

for plan in plans:
    if plan.item:
        item_details = frappe.db.get_value(
            "Item",
            plan.item,
            ["disabled", "has_variants"],
            as_dict=True,
        )

        if item_details:
            if not item_details.disabled and not item_details.has_variants:
                available = plan.name not in blocked_plans

                if available:
                    available_count = available_count + 1
                else:
                    occupied_count = occupied_count + 1

                # دون فترة: جميع الوحدات وحالتها اليوم
                # مع فترة: الوحدات المتاحة فقط
                if not period_mode or available:
                    units.append({
                        "plan": plan.name,
                        "item": plan.item,
                        "building": plan.custom_building,
                        "amount": plan.cost,
                        "currency": plan.currency,
                        "billing_interval": plan.billing_interval,
                        "billing_interval_count": plan.billing_interval_count,
                        "available": available,
                    })

frappe.response["message"] = {
    "mode": "period" if period_mode else "today",
    "from_date": str(start_date),
    "to_date": str(end_date),
    "units": units,
    "count": len(units),
    "available_count": available_count,
    "occupied_count": occupied_count,
}

lease_name = frappe.form_dict.get("lease")

if not lease_name:
    frappe.throw("يجب تحديد عقد الإيجار.")

lease = frappe.get_doc("Subscription", lease_name)
lease.check_permission("read")

deposit_account = "2130 - Refundable Security Deposits - O"

account = frappe.get_doc("Account", deposit_account)
account.check_permission("read")

currency = lease.get("custom_settlement_currency")

if (
    account.company != lease.company
    or account.account_currency != currency
):
    frappe.throw("شركة أو عملة حساب التأمين تختلف عن العقد.")

required = frappe.utils.flt(
    lease.get("custom_required_security_deposit"), 2
)

entries = frappe.get_all(
    "Journal Entry",
    filters={
        "custom_residential_lease": lease_name,
        "docstatus": ["in", [0, 1]]
    },
    fields=["name"],
    limit_page_length=0
)

collected = 0
draft_receipts = 0
refunded = 0
deducted = 0
draft_refunds = 0
draft_deductions = 0

for item in entries:

    entry = frappe.get_doc("Journal Entry", item.name)
    entry.check_permission("read")

    deposit_debit = 0
    deposit_credit = 0
    has_deposit = False

    for row in entry.get("accounts") or []:
        if row.account == deposit_account:
            has_deposit = True
            deposit_debit = deposit_debit + frappe.utils.flt(
                row.debit_in_account_currency, 2
            )
            deposit_credit = deposit_credit + frappe.utils.flt(
                row.credit_in_account_currency, 2
            )

    if has_deposit:

        if entry.company != lease.company:
            frappe.throw("شركة قيد التأمين تختلف عن العقد: " + entry.name)

        deposit_debit = frappe.utils.flt(deposit_debit, 2)
        deposit_credit = frappe.utils.flt(deposit_credit, 2)

        action = entry.get("custom_security_deposit_action") or ""

        if not action and deposit_credit > 0 and deposit_debit == 0:
            action = "Deposit Receipt"

        if action == "Deposit Receipt":

            if deposit_credit <= 0 or deposit_debit != 0:
                frappe.throw("قيد تحصيل التأمين غير صحيح: " + entry.name)

            if entry.docstatus == 1:
                collected = collected + deposit_credit
            else:
                draft_receipts = draft_receipts + deposit_credit

        elif action in ["Deposit Refund", "Deposit Settlement"]:

            if deposit_debit <= 0 or deposit_credit != 0:
                frappe.throw("قيد رد التأمين أو خصمه غير صحيح: " + entry.name)

            cash_amount = 0
            deduction_amount = 0

            for row in entry.get("accounts") or []:
                if row.account != deposit_account:

                    debit = frappe.utils.flt(
                        row.debit_in_account_currency, 2
                    )
                    credit = frappe.utils.flt(
                        row.credit_in_account_currency, 2
                    )

                    if debit != 0 or credit < 0:
                        frappe.throw(
                            "أسطر مقابل رد التأمين أو الخصم يجب أن تكون دائنة: "
                            + entry.name
                        )

                    if credit > 0:
                        counterpart = frappe.db.get_value(
                            "Account",
                            row.account,
                            [
                                "company",
                                "account_currency",
                                "account_type",
                                "root_type"
                            ],
                            as_dict=True
                        )

                        if not counterpart:
                            frappe.throw("الحساب غير موجود: " + row.account)

                        if (
                            counterpart.company != lease.company
                            or counterpart.account_currency != currency
                        ):
                            frappe.throw(
                                "شركة أو عملة الحساب المقابل غير صحيحة: "
                                + entry.name
                            )

                        if counterpart.account_type in ["Bank", "Cash"]:
                            cash_amount = cash_amount + credit

                        elif counterpart.root_type in ["Expense", "Income"]:
                            deduction_amount = deduction_amount + credit

                        else:
                            frappe.throw(
                                "لا يمكن تصنيف الحساب المقابل ضمن الرد أو الخصم: "
                                + row.account
                                + " — "
                                + entry.name
                            )

            cash_amount = frappe.utils.flt(cash_amount, 2)
            deduction_amount = frappe.utils.flt(deduction_amount, 2)

            difference = frappe.utils.flt(
                deposit_debit - cash_amount - deduction_amount, 2
            )

            if difference != 0:
                frappe.throw(
                    "إجمالي الرد النقدي والخصم لا يساوي المبلغ المسحوب من التأمين: "
                    + entry.name
                )

            if entry.docstatus == 1:
                refunded = refunded + cash_amount
                deducted = deducted + deduction_amount
            else:
                draft_refunds = draft_refunds + cash_amount
                draft_deductions = draft_deductions + deduction_amount

        else:
            frappe.throw(
                "يجب تحديد نوع حركة التأمين في القيد: " + entry.name
            )

collected = frappe.utils.flt(collected, 2)
draft_receipts = frappe.utils.flt(draft_receipts, 2)
refunded = frappe.utils.flt(refunded, 2)
deducted = frappe.utils.flt(deducted, 2)
draft_refunds = frappe.utils.flt(draft_refunds, 2)
draft_deductions = frappe.utils.flt(draft_deductions, 2)

draft_outgoing = frappe.utils.flt(
    draft_refunds + draft_deductions, 2
)

balance = frappe.utils.flt(
    collected - refunded - deducted, 2
)

available_refund = frappe.utils.flt(
    balance - draft_outgoing, 2
)

frappe.response["message"] = {
    "currency": currency,
    "required": required,
    "collected": collected,
    "drafts": draft_receipts,
    "remaining": max(
        frappe.utils.flt(required - collected, 2), 0
    ),
    "available_for_new": max(
        frappe.utils.flt(
            required - collected - draft_receipts, 2
        ), 0
    ),
    "excess": max(
        frappe.utils.flt(
            collected + draft_receipts - required, 2
        ), 0
    ),
    "refunded": refunded,
    "settled": deducted,
    "deducted": deducted,
    "draft_refunds": draft_refunds,
    "draft_deductions": draft_deductions,
    "draft_outgoing": draft_outgoing,
    "balance": balance,
    "available_refund": max(available_refund, 0),
    "outgoing_excess": max(-available_refund, 0)
}

lease_name = frappe.form_dict.get("lease")

if not lease_name:
    frappe.throw("يجب تحديد عقد الإيجار.")

lease = frappe.get_doc("Subscription", lease_name)
lease.check_permission("read")

if lease.party_type != "Customer" or not lease.party:
    frappe.throw("العقد يجب أن يكون مرتبطًا بمستأجر.")

if not lease.start_date or not lease.end_date:
    frappe.throw("يجب تحديد بداية العقد ونهايته.")

start = frappe.utils.getdate(lease.start_date)
end = frappe.utils.getdate(lease.end_date)
today = frappe.utils.getdate(frappe.utils.today())

if end < start:
    frappe.throw("نهاية العقد تسبق بدايته.")

currency = lease.get("custom_settlement_currency")
if not currency:
    frappe.throw("يجب تحديد عملة التسوية في العقد.")

if lease.get("follow_calendar_months"):
    frappe.throw(
        "هذا التقرير يحسب الاستحقاق الشهري من تاريخ بداية العقد. "
        + "ألغِ Follow Calendar Months إذا كان هذا هو الاتفاق."
    )

monthly_rent = 0

for row in lease.get("plans") or []:

    if not row.plan:
        frappe.throw("يوجد سطر إيجار دون خطة.")

    plan = frappe.get_doc("Subscription Plan", row.plan)
    plan.check_permission("read")

    if (
        plan.billing_interval != "Month"
        or frappe.utils.cint(plan.billing_interval_count) != 1
        or plan.price_determination != "Fixed Rate"
    ):
        frappe.throw(
            "هذا التقرير مخصص للإيجار الشهري بسعر ثابت. راجع الخطة: "
            + plan.name
        )

    if plan.currency != currency:
        frappe.throw("عملة خطة الإيجار تختلف عن عملة العقد.")

    quantity = frappe.utils.flt(row.qty)
    rate = frappe.utils.flt(plan.cost)

    if quantity <= 0 or rate <= 0:
        frappe.throw("كمية وسعر الإيجار يجب أن يكونا أكبر من صفر.")

    monthly_rent = monthly_rent + rate * quantity

monthly_rent = frappe.utils.flt(monthly_rent, 2)

if monthly_rent <= 0:
    frappe.throw("لم يتم تحديد قيمة الإيجار الشهري.")

if (
    frappe.utils.flt(lease.get("additional_discount_percentage")) != 0
    or frappe.utils.flt(lease.get("additional_discount_amount")) != 0
):
    frappe.throw(
        "يوجد خصم إضافي على العقد؛ يلزم تضمينه في حساب قيمة الإيجار أولًا."
    )

end_exclusive = frappe.utils.getdate(
    frappe.utils.add_days(end, 1)
)

period_count = 0
due_count = 0
period_start = start

while period_start < end_exclusive:

    if period_count >= 1200:
        frappe.throw("مدة العقد تتجاوز الحد المدعوم في التقرير.")

    next_start = frappe.utils.getdate(
        frappe.utils.add_months(start, period_count + 1)
    )

    if next_start > end_exclusive:
        frappe.throw(
            "هذا التقرير مخصص لعقود تتكون من أشهر إيجارية كاملة؛ "
            + "الفترة الأخيرة الجزئية تحتاج تحديد طريقة احتسابها."
        )

    if period_start <= today:
        due_count = due_count + 1

    period_count = period_count + 1
    period_start = next_start

contract_value = frappe.utils.flt(
    monthly_rent * period_count, 2
)

due_rent = frappe.utils.flt(
    monthly_rent * due_count, 2
)

# أصناف الإيجار الموجودة في خطط العقد
rent_items = []

for plan_row in lease.get("plans") or []:
    rent_item = frappe.db.get_value(
        "Subscription Plan", plan_row.plan, "item"
    )

    if rent_item and rent_item not in rent_items:
        rent_items.append(rent_item)

# الفواتير المعتمدة الخاصة بالعقد
invoice_names = frappe.get_all(
    "Sales Invoice",
    filters={
        "subscription": lease.name,
        "company": lease.company,
        "customer": lease.party,
        "docstatus": 1,
        "is_return": 0
    },
