        if row.get("frequency") not in allowed_frequencies:
            frappe.throw(row_label + "يرجى تحديد دورية صحيحة.")

        # تعبئة العملة إذا كانت فارغة، والتحقق من تطابقها
        if not row.get("currency"):
            row.currency = lease_currency

        if row.currency != lease_currency:
            frappe.throw(
                row_label
                + "عملة الخدمة يجب أن تطابق عملة الإيجار: "
                + str(lease_currency)
            )

        # استخدام مدة العقد إذا تُركت تواريخ الخدمة فارغة
        if not row.get("start_date"):
            row.start_date = doc.start_date

        if not row.get("end_date"):
            row.end_date = doc.end_date

        service_start = frappe.utils.getdate(row.start_date)
        service_end = frappe.utils.getdate(row.end_date)

        if service_end < service_start:
            frappe.throw(
                row_label + "نهاية الخدمة يجب ألا تسبق بدايتها."
            )

        if service_start < lease_start or service_end > lease_end:
            frappe.throw(
                row_label + "فترة الخدمة يجب أن تكون داخل مدة العقد."
            )
